estimate_transformations <- function(training, cfg) { dynamic <- c(mintemp="mintemp", soilmoist="soilmoist", leafarea="leafarea", rhum="rhum"); static <- c(cattle="cattle", horses="horses", pigs="pigs", sheep="sheep", goats="goats", road_density="road_density", night_illumination="night_illumination"); cs <- function(nm) c(center=mean(training[[nm]],na.rm=TRUE), scale=max(sd(training[[nm]],na.rm=TRUE), .Machine$double.eps)); list(dynamic=lapply(dynamic, cs), static=lapply(static, function(nm) c(impute=0, center=mean(log1p(training[[nm]]),na.rm=TRUE), scale=max(sd(log1p(training[[nm]]),na.rm=TRUE),.Machine$double.eps))), northing=c(origin=min(training$y,na.rm=TRUE)-25,center=0,scale=1), temperature_hinge=cfg$transformations$temperature_hinge, type="training_only") }
apply_transformations <- function(data, spec, include_hinge=TRUE) { for (nm in names(spec$dynamic)) data[[paste0(nm,"_z")]] <- (data[[nm]]-spec$dynamic[[nm]]["center"])/spec$dynamic[[nm]]["scale"]; for (nm in names(spec$static)) { v <- data[[nm]]; v[is.na(v)] <- spec$static[[nm]]["impute"]; data[[paste0(nm,"_log1p")]] <- log1p(v) }; data$northing_z <- (data$y-spec$northing["origin"]-spec$northing["center"])/spec$northing["scale"]; if (include_hinge && "mintemp" %in% names(data)) data$tmin_hinge <- pmax(0,data$mintemp-spec$temperature_hinge); data }
